// Dump /api/calls (depth 1) for every symbol that writes a call, in both projects, on a fresh run
// generated by the binary under test over a copy of .studio. Usage: node dump-calls.js <out-dir> [bin]
'use strict';
const fs = require('fs'), path = require('path');
const L = require('C:/Users/beatl/Documents/Projetos/librarian/tools/precisao/lib.js');
const out = process.argv[2], bin = process.argv[3] || path.join(L.REPO, 'target/release');
const studio = path.join(L.REPO, '.studio');
const keys = ['healthchecks-25597e41', 'renderer-9b78f3a9'];
fs.mkdirSync(out, { recursive: true });
(async () => {
  await L.withStudio({ studio, bin, keys }, async ({ api, root }) => {
    for (const key of keys) {
      const { id: run } = await api('POST', '/api/generate', { key });
      const G = L.loadGraph(root, key, run);
      fs.copyFileSync(path.join(root, '.studio', 'projects', key, 'runs', run, 'graph-v2.json'), path.join(out, `${key}.graph.json`));
      const owners = new Set();
      for (const e of G.g.edges) if (e.kind === 'observes' && /call_observed$/.test(G.g.nodes[e.to].kind)) owners.add(e.from);
      const res = {};
      const t = n => ({ label: G.g.nodes[n].label, kind: G.g.nodes[n].kind, at: G.where(n) });
      for (const o of [...owners].sort()) {
        const c = await api('POST', '/api/calls', { key, run, node: o, depth: 1, chosen: {} });
        res[o] = {
          owner: t(o),
          links: c.links.map(l => ({ occ: l.occurrence, text: l.text.split(/\r?\n/)[0], line: l.evidence.start_line, path: l.evidence.path, sb: l.evidence.start_byte, eb: l.evidence.end_byte, resolution: l.resolution, basis: l.basis, candidates: l.candidates, edge: l.candidate_edge, to: t(l.to) })),
          unresolved: c.unresolved.map(u => ({ occ: u.occurrence, text: (u.text || '').split(/\r?\n/)[0], line: u.evidence?.start_line, path: u.evidence?.path, sb: u.evidence?.start_byte, eb: u.evidence?.end_byte, reason: u.reason, resolution: u.resolution, candidates: u.candidates, to: u.to ? t(u.to) : null })),
        };
      }
      fs.writeFileSync(path.join(out, `${key}.calls.json`), JSON.stringify({ run, res }, null, 0));
      console.log(key, run, Object.keys(res).length, 'donos');
    }
  });
})().catch(e => { console.error(e); process.exit(2); });
